(async () => {
  const { readFileSync, existsSync } = await import('node:fs');
  const csvPath = process.env.CSV_PATH;
  if (!csvPath) throw new Error('Missing env var CSV_PATH');
  if (!existsSync(csvPath)) throw new Error('CSV file not found at ' + csvPath);
  const content = readFileSync(csvPath, { encoding: 'utf8' });
  globalThis._csvContent = content;
})();

(async () => {
  const papaparse = await import('papaparse');
  const Papa = papaparse.default || papaparse;
  if (typeof Papa.parse !== 'function') throw new Error('papaparse: required method parse not in exports');
  const content = globalThis._csvContent;
  const result = Papa.parse(content, { header: true, skipEmptyLines: true });
  if (!result || !Array.isArray(result.data)) throw new Error('Parsing failed');
  globalThis._parsed = result.data;
})();

(async () => {
  const data = globalThis._parsed;
  const jsonStr = JSON.stringify(data);
  console.log(JSON.stringify({ json: jsonStr }));
})();
